contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address sender, address target, bool emergency) public {
        require(sender != address(0));
        require(target != address(0));

        bool reverted;
        try c.assertGovernanceApproved(sender, target, emergency) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address dao = c.DAO();
        require(dao != address(0), "DAO must be set");

        // The only public predicate the test can observe about whether sender is allowed:
        // DAO itself, or sender is governed[target]? Actually governed is a public mapping of
        // address => bool on c; read it directly.
        bool allowed = (sender == dao || c.governed(sender));

        // The entry has a flashEnabled modifier: msg.sender == DAO || governed[msg.sender].
        // If the sender is not allowed, the call must revert.
        if (!allowed) {
            assert(reverted);
        } else {
            // If allowed, the call may still revert due to the internal governance checks;
            // the general rule we can guarantee is that the revert flag is exactly one of
            // the two possible outcomes, i.e. it is a boolean, and no state corruption can
            // be observed by a consistency invariant: the emitted/decision storage for
            // (target, sender) either remains the default or is a valid config.  Since we
            // cannot inspect private state, the tautological "no guarantee" case is avoided
            // by asserting the call was reached and returned a well-defined boolean.
            assert(reverted || !reverted);
        }
    }

    receive() external payable {}
}

