contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint8 maxGovernanceChangePerEpoch, uint256 epochSize, uint8 changeTolerance) public payable {
        require(maxGovernanceChangePerEpoch == 0 && changeTolerance == 0);

        c.endConfiguration();

        bool reverted;
        try c.configureSecurityParameters(maxGovernanceChangePerEpoch, epochSize, changeTolerance) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (, uint256 lastFlashGovernanceAct, , ) = c.security();
        (uint256 amount, uint256 unlockTime, address asset, bool assetBurnable) = c.flashGovernanceConfig();
        (uint256 storedEpochSize, , uint8 storedMaxGovernanceChangePerEpoch, uint8 storedChangeTolerance) = c.security();

        assert(
            reverted ||
            (storedEpochSize == epochSize &&
             storedMaxGovernanceChangePerEpoch == maxGovernanceChangePerEpoch &&
             storedChangeTolerance == changeTolerance &&
             lastFlashGovernanceAct == 0 &&
             amount == 0 &&
             unlockTime == 0 &&
             asset == address(0) &&
             assetBurnable == false)
        );
    }

    receive() external payable {}
}

