        require(!firstReverted);
        require(assetAfterFirst == address(0));

        bool secondReverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        assert(secondReverted);
    }

