contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint8 maxGovernanceChangePerEpoch, uint256 epochSize, uint8 changeTolerance) public {
        // The DAO is the only address allowed on a configured contract.
        require(msg.sender == address(this), "sender guard");

        // If the contract is not configured yet, onlySuccessfulProposal is bypassed.
        // If it is configured, msg.sender (this test contract) is the deployer of C,
        // and Governable.setDAO allows msg.sender == DAO. But successfulProposal
        // is checked against DAO in LimboDAOLike; we cannot assume it returns true.
        // To keep the rule deterministic we only assert the changeTolerance guard
        // when the call is otherwise permitted: either !configured or the DAO
        // says the successful proposal passed. We can only observe `configured()`.
        bool preConfigured = c.configured();

        bool reverted;
        try c.configureSecurityParameters(maxGovernanceChangePerEpoch, epochSize, changeTolerance) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: when the caller is allowed by the proposal gate
        // (i.e. the contract is not yet configured), the ONLY remaining rejection
        // reason is changeTolerance >= 100. When configured, the proposal gate
        // itself may reject, which we cannot distinguish from the tolerance check,
        // so we assert the implication only on the not-yet-configured path.
        if (!preConfigured) {
            assert(reverted == (changeTolerance >= 100));
        } else {
            // Once configured, the call succeeds only if the proposal gate passes;
            // if it passes, the tolerance guard again forces revert == (changeTolerance >= 100).
            // The failure of the call can only ever be caused by one of those two guards,
            // so success implies changeTolerance < 100.
            if (!reverted) {
                assert(changeTolerance < 100);
            } else {
                assert(true);
            }
        }
    }

    receive() external payable {}
}

contract InvMutTest {
