        bool reverted;
        try c.configureSecurityParameters(maxGovernanceChangePerEpoch, epochSize, changeTolerance) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 storedMaxChange, uint256 storedEpochSize, uint8 storedTolerance) = c.security();

