        // Capture the public config and the caller's pending decision before the call
        address configuredAsset;
        uint256 configuredAmount;
        uint256 configuredUnlockTime;
        bool configuredBurnable;
        (configuredAsset, configuredAmount, configuredUnlockTime, configuredBurnable) = c.flashGovernanceConfig();

        uint256 pendingUnlockTime;
        uint256 pendingAmount;
        address pendingAsset;
        bool pendingBurnable;
        (pendingAmount, pendingUnlockTime, pendingAsset, pendingBurnable) = c.pendingFlashDecision(target, sender);

        uint256 lastActBefore;
        uint256 epochSize;
        uint256 lastFlashGovernanceAct;
        uint8 maxGovernanceChangePerEpoch;
        uint8 changeTolerance;
        (epochSize, lastFlashGovernanceAct, maxGovernanceChangePerEpoch, changeTolerance) = c.security();
        lastActBefore = lastFlashGovernanceAct;

        // Determine whether the asset transfer will succeed by observing what the token would return.
        // We cannot call an arbitrary IERC20 we don't own; instead infer from config (amount zero => transfer may still fail or succeed, but we rely on revert observation).
        bool reverted;
        try c.assertGovernanceApproved(sender, target, emergency) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state
        uint256 postUnlockTime;
        ( , postUnlockTime, , ) = c.pendingFlashDecision(target, sender);
        ( , uint256 postLastAct, , ) = c.security();

        // The rule: if the call succeeded, the security.lastFlashGovernanceAct must have been set to block.timestamp,
        // and pending.unlockTime must equal block.timestamp + configuredUnlockTime
        // (both observable). If the call reverted, no state change to the pending decision's unlock time
        // relative to before when it was previously zero OR it remains as before if previously set.
        // We assert the observable invariant: a successful call updates the pending unlock time to a non-zero value
        // equal to block.timestamp + configuredUnlockTime, and records lastFlashGovernanceAct.
        assert(
            (reverted && postUnlockTime == pendingUnlockTime) ||
            (!reverted && postUnlockTime == block.timestamp + configuredUnlockTime && postLastAct == block.timestamp)
        );
    }

    receive() external payable {}
}

