contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address targetContract,
        address asset,
        uint256 amount,
        uint256 unlockTime,
        bool assetBurnable
    ) public {
        // Configure flash governance for this contract (msg.sender on c will be address(this)).
        // onlySuccessfulProposal gate: DAO is unconfigured initially in a fresh deployment,
        // so configured == false and assertSuccessfulProposal passes.
        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        // Read the pending decision before the deciding call.
        (uint256 beforeAmount, uint256 beforeUnlockTime, address beforeAsset, bool beforeBurnable) =
            c.pendingFlashDecision(targetContract, address(this));

        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 afterAmount, uint256 afterUnlockTime, address afterAsset, bool afterBurnable) =
            c.pendingFlashDecision(targetContract, address(this));

        // A withdrawal only succeeds when the stored pending decision itself
        // has the exact requested asset, a positive amount, and an unlock time
        // strictly in the past. Otherwise it must revert.
        bool eligible =
            beforeAsset == asset &&
            beforeAmount > 0 &&
            beforeUnlockTime < block.timestamp;

        if (!eligible) {
            assert(reverted);
        } else {
            // When eligible, either the ERC20 transfer reverted (and state is
            // unchanged) or the withdrawal completed and cleared the entry.
            assert(reverted || (afterAmount == 0 && afterAsset == address(0)));
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address targetContract,
        address asset,
        uint256 amount,
        uint256 unlockTime,
        bool assetBurnable
    ) public {
        // Setup: configure flash governance so that a pending decision can be created.
        // In a fresh deployment configured == false, so onlySuccessfulProposal passes.
        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        // Seed a pending decision for the caller (address(this)) on this target.
        // assertGovernanceApproved is flashEnabled and msg.sender == DAO? No: DAO is non-zero and
        // governed[msg.sender] is false, so this would revert. Instead use the fact that the
        // pending map can only be populated via assertGovernanceApproved, which we cannot reach here.
        // Therefore the only observable pre-state is the all-zero default for the pending entry.
        // Read the pending decision before the deciding call.
        (uint256 beforeAmount, uint256 beforeUnlockTime, address beforeAsset, bool beforeBurnable) =
            c.pendingFlashDecision(targetContract, address(this));

        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 afterAmount, uint256 afterUnlockTime, address afterAsset, bool afterBurnable) =
            c.pendingFlashDecision(targetContract, address(this));

        // Eligibility is determined purely by the stored pending decision value:
        // exact asset match, positive amount, and unlockTime strictly in the past.
        bool eligible =
            beforeAsset == asset &&
            beforeAmount > 0 &&
            beforeUnlockTime < block.timestamp;

        // General rule: if not eligible the call must revert; if eligible it must succeed
        // (no revert) and clear the pending entry. When the entry is the all-zero default,
        // it is eligible only if asset == address(0), amount == 0 fails the >0 check, so
        // the default entry is never eligible and the call must revert.
        assert(
            eligible
                ? (!reverted && afterAmount == 0 && afterAsset == address(0))
                : reverted
        );
    }

    receive() external payable {}
}

