contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256 v1, uint256 v2, uint256 setV1, uint256 setV2) public payable {
        // Precondition: avoid unsigned multiplication overflow in the expected formula,
        // and make v1, v2 small enough for the expected relative-difference reasoning.
        require(v1 <= 1e18 && v2 <= 1e18, "params too large");
        require(setV1 <= 1e18 && setV2 <= 1e18, "params too large");

        // Drive c.enforceTolerance on the setup values first (may revert or not, but that
        // call's outcome is part of the state transition we then observe).
        c.enforceTolerance(setV1, setV2);

        // Read tolerance parameter from public getter; if never configured it is 0.
        (, , uint8 changeTolerance) = c.security();

        // The deciding call with caller-controlled values.
        bool reverted;
        try c.enforceTolerance(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: revert exactly when both values are nonzero and the relative
        // difference is at least changeTolerance percent of v1.
        //   reverted  <=>  v1 != 0 && v2 != 0 && ((|v1-v2| * 100) >= changeTolerance * v1)
        // Since v3 == 0 and limits are inactive for this fresh caller, the guard does not
        // short-circuit; the rule holds independent of the setup values.
        bool expectedRevert;
        if (v1 == 0 || v2 == 0) {
            expectedRevert = false;
        } else {
            uint256 diff = v1 > v2 ? v1 - v2 : v2 - v1;
            expectedRevert = (diff * 100) >= (uint256(changeTolerance) * v1);
        }

        assert(reverted == expectedRevert);
    }

    receive() external payable {}
}

