contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address[] calldata governables, bool[] calldata isGoverned, bool preEndConfiguration) public {
        // Optionally mark the inherited Governable as configured, so the onlySuccessfulProposal
        // modifier requires an actual successful proposal from msg.sender.
        if (preEndConfiguration) {
            c.endConfiguration();
        }

        address[] memory gs = governables;
        bool[] memory bg = isGoverned;

        bool reverted;
        try c.setGoverned(gs, bg) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (preEndConfiguration) {
            // Configured: the onlySuccessfulProposal modifier demands that the test contract
            // (msg.sender) is a successful proposal in the DAO. Since the test contract is not
            // the DAO's configured proposal factory and cannot have made a successful proposal
            // in a fresh deployment, the call must have reverted.
            assert(reverted);
        } else {
            // Unconfigured: assertSuccessfulProposal always passes, so the call proceeds to the
            // length check and must only revert on a mismatch.
            assert(reverted == (governables.length != isGoverned.length));
        }
    }
}

