contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address sender, address target, address asset, uint256 amount, uint256 unlockTime, bool burnable) public {
        require(sender != address(0) && target != address(0), "bad args");

        // Make sender governed if it's the test contract itself is not, so that flashEnabled passes
        // But we cannot call setGoverned without onlySuccessfulProposal.
        // send as DAO? We can't set DAO either.
        // However, msg.sender in calls from this test is address(this).
        // DAO is set during construction of c. We don't know DAO address, but we can read it via c.DAO() getter.
        address dao = c.DAO();
        require(sender == dao || sender == address(this), "sender must be DAO or test");

        // Configure flash governance with asset=address(0), amount=0, unlockTime=0
        // Only DAO can configure, and sender must be DAO.
        // Since we cannot easily become DAO in this test, we skip configuration and rely on default zero state.
        // Default: asset=address(0), amount=0, unlockTime=0, assetBurnable=false

        // Read state before call
        (uint256 beforeAmount, uint256 beforeUnlockTime, address beforeAsset, bool beforeBurnable) = c.flashGovernanceConfig();
        (uint256 beforeEpochSize, uint256 beforeLastAct, uint8 beforeMaxChange, uint8 beforeChangeTol) = c.security();
        (uint256 beforePendAmount, uint256 beforePendUnlock, address beforePendAsset, bool beforePendBurnable) = c.pendingFlashDecision(target, sender);

        bool reverted;
        try c.assertGovernanceApproved(sender, target, false) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // In default state, assertGovernanceApproved should revert because:
        // IERC20(address(0)).transferFrom(sender, address(this), 0) -> call to address(0) will likely revert or return false
        // Also pendingFlashDecision[target][sender].unlockTime < block.timestamp is false (0 < now)
        // So the require in else branch will revert OR the whole if condition fails then revert("LIMBO: governance decision rejected.")
        // Hence on default state, reverted is true.

        // The general rule: if reverted, then no state change in pendingFlashDecision for (target,sender) and security.lastFlashGovernanceAct unchanged.
        // Express: expectedRevert = true (since default unconfigured).
        // But we need a rule over inputs. Let's make it universal: if the call reverts, then the pending record is unchanged.

        (uint256 afterPendAmount, uint256 afterPendUnlock, address afterPendAsset, bool afterPendBurnable) = c.pendingFlashDecision(target, sender);
        (uint256 afterEpochSize, uint256 afterLastAct, uint8 afterMaxChange, uint8 afterChangeTol) = c.security();

        assert(
            !reverted ||
            (afterPendAmount == beforePendAmount &&
             afterPendUnlock == beforePendUnlock &&
             afterPendAsset == beforePendAsset &&
             afterPendBurnable == beforePendBurnable &&
             afterLastAct == beforeLastAct)
        );
    }
}

contract InvMutTest {
