        // Read before-state through public getters.
        (uint256 beforeAmt, uint256 beforeUnlock, address beforeAsset, bool beforeBurnable) = c.pendingFlashDecision(target, sender);
        (uint256, uint256 beforeLastAct, uint8, uint8) = c.security();

        bool reverted;
        try c.assertGovernanceApproved(sender, target, false) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 afterAmt, uint256 afterUnlock, address afterAsset, bool afterBurnable) = c.pendingFlashDecision(target, sender);
        (uint256, uint256 afterLastAct, uint8, uint8) = c.security();

        if (reverted) {
            // A revert must not change the pending record nor the security activity marker.
            assert(
                afterAmt == beforeAmt &&
                afterUnlock == beforeUnlock &&
                afterAsset == beforeAsset &&
                afterBurnable == beforeBurnable &&
                afterLastAct == beforeLastAct
            );
        } else {
            // Success copies the whole flashGovernanceConfig into the pending record and advances the marker.
            (uint256 cfgAmt, uint256 cfgUnlock, address cfgAsset, bool cfgBurnable) = c.flashGovernanceConfig();
            assert(
                afterAmt == cfgAmt &&
                afterAsset == cfgAsset &&
                afterBurnable == cfgBurnable &&
                afterLastAct >= beforeLastAct
            );
        }
    }
}

