contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256 v1, uint256 v2, uint256 maxChange, uint256 epochSize, uint256 tol) public {
        // Configure enforcement state through public surfaces only.
        c.setEnforcement(true);
        c.configureSecurityParameters(uint8(maxChange), epochSize, uint8(tol));

        bool reverted;
        try c.enforceTolerance(v1, v2) { reverted = false; } catch { reverted = true; }

        // On inputs with both values small (<=1), no revert may occur even if enforcement is on,
        // because the small-value branch is unconditional.
        // Conversely, whenever tolerance requirements are violated with both values > 1,
        // enforceTolerance must revert.
        bool small = v1 <= 1 && v2 <= 1;
        bool viol = false;
        if (v1 > v2) {
            if (v2 == 0) viol = v1 > 1;
            else viol = ((v1 - v2) * 100) >= tol * v1;
        } else {
            if (v1 == 0) viol = v2 > 1;
            else viol = ((v2 - v1) * 100) >= tol * v1;
        }

        if (small) {
            assert(!reverted);
        } else if (viol) {
            assert(reverted);
        }
    }

    receive() external payable {}
}

