contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 v1, uint256 v2, bool enforce, bool cfg) public {
        c.setEnforcement(enforce);

        bool reverted = false;
        try c.enforceTolerance(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool enforcementActive = enforce && cfg;

        if (!enforcementActive) {
            assert(!reverted);
        } else if (v1 > v2) {
            if (v2 == 0) {
                assert(reverted == (v1 > 1));
            } else {
                assert(block.timestamp >= 0);
            }
        } else {
            if (v1 == 0) {
                assert(reverted == (v2 > 1));
            } else {
                assert(block.timestamp >= 0);
            }
        }
    }

    receive() external payable {}
}

