contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address sender, address[] memory governables, bool[] memory statuses, bool dummyEmergency) public payable {
        require(governables.length == statuses.length, "test input lengths must match");
        require(governables.length > 0, "must test at least one governable entry");

        // Read whether c is configured before the deciding call; this is only a view call.
        bool isConfigured = c.configured();

        // Record the current state for the chosen protocol "sender" (the account the DAO sees as proposer).
        // This does not change state, but we need the observing call to be its own top-level statement,
        // so we assign it.
        bool senderWasGovernedBefore = c.governed(sender);

        bool reverted;
        try c.setGoverned(governables, statuses) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool senderIsGovernedAfter = c.governed(sender);

        address[] memory zeroGovernables = new address[](0);
        bool[] memory zeroStatuses = new bool[](0);
        bool mismatchReverted;
        try c.setGoverned(zeroGovernables, new bool[](1)) {
            mismatchReverted = false;
        } catch {
            mismatchReverted = true;
        }

        // General rule: a length-mismatched setGoverned call must always revert.
        assert(mismatchReverted);

        // General rule about the well-formed call:
        // if c is not configured, setGoverned must not revert; if it is configured, it must revert
        // unless there is a successful proposal for the Protocol DAO, which is not observable here,
        // so we only assert the unconditional implication: reverted => (isConfigured || senderIsGovernedAfter != senderWasGovernedBefore || senderIsGovernedAfter == statuses[0]).
        // That implication is too weak; instead, assert the observable atomicity/consistency guarantee:
        // For every i, after a non-reverting call, governed(governables[i]) equals statuses[i];
        // and if the call reverts, at least the first entry may be unchanged or changed? We need a true invariant.
        // The actual invariant we can prove from the code is: if the call succeeds, all entries are applied atomically;
        // if the call reverts due to the onlySuccessfulProposal check, no entry is applied.
        // We cannot observe all entries without looping and reading c.governed, which is allowed (view call).
        // We assert the atomic consistency for the first entry and, if length > 1, that all entries were applied.
        // Since we cannot easily express all in one formula without loops, we assert:
        // (1) mismatchReverted is true (done above), and
        // (2) if !reverted then c.governed(governables[0]) == statuses[0],
        // (3) if reverted then c.governed(governables[0]) == senderWasGovernedBefore OR !isConfigured? No, if reverted, no state change is guaranteed because the revert may occur before any writes, but also writes may have happened before revert? In setGoverned, the revert can only happen at the onlySuccessfulProposal modifier before the loop, so no writes occur. So if reverted, all entries unchanged. We can assert that.

        if (!reverted) {
            assert(c.governed(governables[0]) == statuses[0]);
        } else {
            assert(c.governed(governables[0]) == senderWasGovernedBefore || governables[0] != sender);
        }

        // Remove the extra unused variable warning by referencing dummyEmergency in a harmless way
        // (not part of the rule, but the parameter is required by the interface of run; we can leave it unused).
        dummyEmergency;
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address[] memory governables, bool[] memory statuses) public payable {
        require(governables.length > 0, "must test at least one entry");

        address firstGovernable = governables[0];
        bool firstStatus = statuses[0];
        bool firstWasGoverned = c.governed(firstGovernable);

        bool mismatchReverted;
        if (governables.length == statuses.length) {
            address[] memory badGovernables = new address[](governables.length + 1);
            bool[] memory badStatuses = new bool[](governables.length);
            for (uint256 i = 0; i < governables.length; i++) {
                badGovernables[i] = governables[i];
                badStatuses[i] = statuses[i];
            }
            try c.setGoverned(badGovernables, badStatuses) {
                mismatchReverted = false;
            } catch {
                mismatchReverted = true;
            }
        } else {
            try c.setGoverned(governables, statuses) {
                mismatchReverted = false;
            } catch {
                mismatchReverted = true;
            }
        }

        bool lengthMismatchReverted;
        if (governables.length == statuses.length) {
            address[] memory shortGovernables = new address[](governables.length - 1);
            for (uint256 i = 0; i < governables.length - 1; i++) {
                shortGovernables[i] = governables[i];
            }
            try c.setGoverned(shortGovernables, statuses) {
                lengthMismatchReverted = false;
            } catch {
                lengthMismatchReverted = true;
            }
        } else {
            lengthMismatchReverted = mismatchReverted;
        }

        bool reverted;
        try c.setGoverned(governables, statuses) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool firstIsGovernedAfter = c.governed(firstGovernable);

        assert(lengthMismatchReverted);

        assert(!reverted || governables.length != statuses.length);

        if (!reverted && governables.length == statuses.length) {
            assert(firstIsGovernedAfter == firstStatus);
            assert(c.governed(firstGovernable) == firstStatus);
        } else {
            assert(firstIsGovernedAfter == firstWasGoverned);
        }
    }

    receive() external payable {}
}

