contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 v1, uint256 v2, uint8 maxChange, uint256 epochSize, uint8 tol) public {
        require(true);

        // Setup: configure security parameters through the public entry point.
        // The call is made directly from this contract; because c is freshly deployed and DAO is this
        // test contract (constructor argument), this must succeed unless maxChange/tol are invalid.
        // Only configure when the values are sane (tol < 100) to avoid setup reverting for all inputs.
        if (tol < 100) {
            c.configureSecurityParameters(maxChange, epochSize, tol);
        } else {
            // For invalid tolerance, the call must revert; record that and skip the rest.
            bool setupReverted;
            try c.configureSecurityParameters(maxChange, epochSize, tol) { setupReverted = false; }
            catch { setupReverted = true; }
            assert(setupReverted && tol >= 100);
            return;
        }

        // Activate enforcement for the caller (this test contract).
        c.setEnforcement(true);

        // Read the configured tolerance from c's public getter; it must equal the parameter we passed.
        (, , , uint8 storedTol) = c.security();

        bool reverted;
        try c.enforceTolerance(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if the call reverted, the tolerance limit must be exceeded.
        // Conversely, whenever the limit is strictly within bounds, the call must not revert.
        bool exceedsLimit;
        if (v1 > v2) {
            if (v2 == 0) {
                exceedsLimit = v1 > 1;
            } else {
                exceedsLimit = ((v1 - v2) * 100) >= storedTol * v1;
            }
        } else {
            if (v1 == 0) {
                exceedsLimit = v2 > 1;
            } else {
                exceedsLimit = ((v2 - v1) * 100) >= storedTol * v1;
            }
        }

        // The assertion: revert status reflects exactly whether the configured tolerance was exceeded.
        assert(reverted == exceedsLimit);
    }

    receive() external payable {}
}
